//go:build webui

package webui

import (
	"embed"
	"io/fs"
)

// dist is generated by `make webui-dist` and never committed; a build with this tag and no dist does not compile (D-149).
//
//go:embed all:dist
var dist embed.FS

// FS is the built interface, rooted at index.html.
func FS() fs.FS {
	sub, err := fs.Sub(dist, "dist")
	if err != nil {
		panic(err) // "dist" is a valid name and is embedded: cannot happen
	}
	return sub
}
